<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';
import {request} from './workbench-api';
import DocumentPicker from './DocumentPicker.vue';
const props=defineProps({initialDocumentId:{type:String,default:''}}),emit=defineEmits(['visual','review']);
const id=ref(props.initialDocumentId),view=ref(null),selected=ref(null),regionPage=ref(1),zoom=ref(100),boxes=ref(true),draft=ref(''),reviewer=ref(''),note=ref(''),inspected=ref(false),baseline=ref(null),busy=ref(false),error=ref(''),notice=ref(''),stale=ref(false);let seq=0;
async function load(reset=true){const token=++seq;error.value='';if(reset){view.value=null;baseline.value=null;regionPage.value=1;selected.value=null;inspected.value=false;note.value='';stale.value=false;}if(!id.value)return;try{const r=await request(`/documents/${id.value}/evidence-comparison?region_page=${regionPage.value}&region_page_size=50`);if(token!==seq)return;view.value=r;selected.value=null;if(reset){baseline.value={expected_revision:r.revision_id,expected_write_version:r.write_version,expected_source_sha256:r.source_sha256,expected_model_fingerprint:r.observations[0]?.fingerprint,expected_label_review_id:r.latest_label_review?.review_id||null};draft.value=r.latest_label_review?.evidence?.source_visible_description||r.observations[0]?.observation.visible_description||'';}else if(r.write_version!==baseline.value?.expected_write_version||(r.latest_label_review?.review_id||null)!==baseline.value?.expected_label_review_id){stale.value=true;error.value='来源或审核记录已变化。请刷新并核对后再保存；当前编辑内容保留。';}}catch(e){if(token===seq)error.value=e.message;}}
function style(r){const b=r.bbox;return {left:b[0]*100+'%',top:b[1]*100+'%',width:b[2]*100+'%',height:b[3]*100+'%'};}
async function save(decision){if(!view.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{await request(`/documents/${id.value}/visual-review`,{method:'POST',body:{...baseline.value,source_visible_description:draft.value,reviewer:reviewer.value,note:note.value,decision,source_inspected:inspected.value}});notice.value=decision==='rejected'?'画面标签已撤回，历史和模型原文保留。':'修正与审核已保存，可用于当前来源的画面标签检索。';await load(true);}catch(e){error.value=e.message;if(e.status===409)stale.value=true;}finally{busy.value=false;}}
watch(id,()=>{notice.value='';load(true);},{immediate:true});watch(()=>props.initialDocumentId,v=>{id.value=v;});onBeforeUnmount(()=>{seq++;});
</script>
<template><section class="wb-card"><small>EVIDENCE COMPARISON</small><h2>图文区域对照</h2><p>点击 OCR 区域核对文字，再按原图修正可见对象和布局。模型描述、OCR 和操作审核分别保留。</p><DocumentPicker v-model="id" label="选择图文资料"/><div class="wb-actions"><button class="wb-button" :disabled="busy||!id" @click="load(true)">刷新来源与审核</button><button v-if="view" class="wb-button" @click="emit('visual',{document_id:id,revision_id:view.revision_id,knowledge_base_id:view.knowledge_base_id})">查看模型及动态图观察</button><button v-if="view" class="wb-button" @click="emit('review',{document_id:id})">版本与资料审核</button></div><div v-if="error" role="alert" class="wb-alert error">{{error}}</div><div v-if="notice" role="status" class="wb-alert">{{notice}}</div>
<template v-if="view"><h3>{{view.source_name}}</h3><p class="wb-muted">{{view.revision_id}} · SHA256 {{view.source_sha256}}</p><div class="compare"><div><div class="wb-actions"><label><input type="checkbox" v-model="boxes"/>显示 OCR 区域</label><label>原图缩放<select v-model="zoom" aria-label="原图缩放"><option :value="100">100%</option><option :value="150">150%</option><option :value="200">200%</option></select></label></div><div class="image-scroll"><div class="image-surface" :style="{width:zoom+'%'}"><img :src="`/api/v2/workbench/documents/${id}/evidence-preview?revision_id=${view.revision_id}`" alt="当前来源首帧与 OCR 区域"/><button v-for="(r,i) in boxes?view.regions:[]" :key="r.region_id" class="region" :class="{selected:selected?.region_id===r.region_id}" :style="style(r)" :aria-label="'OCR 区域 '+(i+1)+' '+r.text" :title="r.text" @click="selected=r"></button></div></div><p class="wb-muted">坐标对应原图首帧，框线来自 OCR。此处不为模型描述虚构区域坐标。</p><a :href="`/api/v2/workbench/documents/${id}/source?revision_id=${view.revision_id}`">下载当前来源原件</a></div><div><h4>OCR 文字与位置</h4><p v-if="view.ocr_provider==='synthetic_fixture'" class="wb-muted">合成验收记录，未调用 OCR 模型。</p><p v-if="!view.region_total">{{view.ocr_status==='no_text'?'OCR 未识别到文字，保留真实空结果。':'当前没有可用的 OCR 区域。'}}</p><div class="ocr-list"><button v-for="(r,i) in view.regions" :key="r.region_id" class="wb-button" :class="{active:selected?.region_id===r.region_id}" @click="selected=r">{{(regionPage-1)*50+i+1}} · {{r.text}}</button></div><div v-if="view.region_total>50" class="wb-between"><button class="wb-button tiny" :disabled="regionPage===1" @click="regionPage--;load(false)">区域上一页</button><span>{{regionPage}} / {{Math.ceil(view.region_total/50)}}</span><button class="wb-button tiny" :disabled="regionPage*50>=view.region_total" @click="regionPage++;load(false)">区域下一页</button></div><article v-if="selected" class="selected-region"><strong>选中区域文字</strong><pre>{{selected.text}}</pre><p>OCR 模型置信度：{{selected.confidence===null?'未提供':selected.confidence.toFixed(3)}} · 坐标 {{selected.bbox.join(', ')}}</p></article><p v-if="view.invalid_regions_omitted" class="wb-muted">{{view.invalid_regions_omitted}} 条异常坐标未绘制，请查看原图。</p></div></div>
<div class="compare observations"><div><h4>模型原始观察</h4><p v-if="!view.observations.length">暂无当前修订描述，请在任务中心生成观察。</p><template v-for="o in view.observations.slice(0,1)" :key="o.fingerprint"><pre>{{(o.raw_observation||o.observation).visible_description}}</pre><p v-if="o.ai_review">已有 AI 修正：{{o.observation.visible_description}}</p><small>描述批次 {{o.fingerprint}}</small><ul><li v-for="u in o.observation.unknowns" :key="u">未知：{{u}}</li></ul></template></div><form @submit.prevent="save('corrected')"><h4>来源核对与画面标签修正</h4><p v-if="view.latest_label_review">最近决定：{{view.latest_label_review.decision}} · {{view.latest_label_review.reviewer}} · {{view.latest_label_review.review_id}}</p><label class="wb-field">可见内容标签<textarea v-model="draft" aria-label="可见内容标签" maxlength="600" rows="4" placeholder="只写原图直接可见的对象、颜色和布局"/></label><label class="wb-field">操作人<input v-model="reviewer" aria-label="画面核对操作人" maxlength="100" required/></label><label class="wb-field">核对说明<textarea v-model="note" aria-label="画面核对说明" maxlength="3000" required rows="2"/></label><label class="inspect"><input type="checkbox" v-model="inspected"/>已查看当前原图并核对上述标签</label><div class="wb-actions"><button class="wb-button primary" :disabled="busy||stale||!inspected||!reviewer.trim()||!note.trim()||!draft.trim()||!baseline?.expected_model_fingerprint">保存修正与审核</button><button type="button" class="wb-button" :disabled="busy||stale||!inspected||!reviewer.trim()||!note.trim()||!baseline?.expected_model_fingerprint" @click="save('rejected')">撤回已核对标签</button></div><p class="wb-muted">保存追加操作审核记录，原件和模型原文保留；不自动发布整份资料，不作为人工金标或现场质量放行。</p></form></div><details><summary>当前修订审核与修正历史（{{view.source_reviews.length}} 条）</summary><article v-for="r in view.source_reviews" :key="r.review_id"><strong>{{r.reviewer}} · {{r.decision}}</strong><p>{{r.scope}} · {{r.review_kind}}</p><p>{{r.note}}</p><small>{{r.created_at}}</small></article></details></template><p v-else-if="!id" class="wb-empty">从文档管理的图片卡片进入，或在上方选择图文资料。</p></section></template>
<style scoped>.compare{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin:20px 0}.compare>div,.compare>form{min-width:0}.image-scroll{overflow:auto;max-height:680px;border:1px solid #d5dce4}.image-surface{position:relative}.image-surface img{display:block;width:100%}.region{position:absolute;min-width:0;padding:0;border:1px solid #d97622;background:#ffdb5822;cursor:pointer;box-sizing:border-box}.region.selected{border:3px solid #a42b16;background:#ffd94666}.ocr-list{display:flex;flex-wrap:wrap;gap:6px;max-height:420px;overflow:auto}.ocr-list button{white-space:normal;text-align:left}.selected-region{padding:12px;background:#eef5fc;margin-top:12px}pre,small,p,h3{white-space:pre-wrap;overflow-wrap:anywhere}.inspect{display:flex;align-items:center;gap:8px}.inspect input,.wb-actions input[type=checkbox]{width:16px;margin:0}article{border-bottom:1px solid #dbe3eb;padding:12px 0}@media(max-width:750px){.compare{grid-template-columns:minmax(0,1fr)}}
</style>
